const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,n=3)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}):'—';
const sign=(v,n=2)=>typeof v==='number'&&Number.isFinite(v)?`${v>0?'+':''}${num(v,n)}`:'—';
const date=v=>!v?'미확인':String(v).includes('T')&&!Number.isNaN(Date.parse(v))?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v)).replaceAll('-','.'):String(v).slice(0,10).replaceAll('-','.');
