function title(n){
 if(names[n]||researchNames[n])return names[n]||researchNames[n];
 const window=String(n).match(/^(.*)_(\d+)m$/);
 if(window&&researchNames[window[1]])return `${researchNames[window[1]]} · ${window[2]}개월`;
 const formation=String(n).match(/^(price_momentum|price_reversal|market_relative_momentum)_(\d+)_(\d+)$/);
 if(formation)return `${({price_momentum:'가격 모멘텀',price_reversal:'가격 반전',market_relative_momentum:'시장 대비 모멘텀'})[formation[1]]} · ${formation[2]}·${formation[3]}개월 설정`;
 return human(n);
}
