const notice=(m,k='amber')=>`<div class="notice ${k}"><span aria-hidden="true">${k==='amber'?'!':'i'}</span><div>${m}</div></div>`;
function freshness(){
 if(comparison)return notice(`<strong>${date(comparison.as_of)} DB 재확인: 현재 승인 ${comparison.factor_count}개, 모두 일별 계산 버전.</strong> 아래 기존 IC·OOS·발견일은 ${date(gold.catalog_as_of||gold.as_of)} 과거 정의의 연구 기록입니다. ${comparison.historical_definition_changed}개는 정의가 달라졌고 ${comparison.historical_definition_unknown}개는 과거 해시가 없어 동일성을 확인할 수 없습니다. 새 버전 성과로 옮겨 붙이지 않았습니다. <a class="text-button" href="#comparison">현재 버전·월초 실행 비교 보기 ↗</a>`,'blue');
 return notice(`성과 표는 <strong>${date(gold.catalog_as_of||gold.as_of)} 승인 스냅샷 ${gold.approved_count}개</strong>의 과거 연구 기록입니다. 현재 버전 비교 스냅샷은 불러오지 못했습니다. 과거 성과를 현재 버전의 결과로 간주하지 않습니다.`);
}
const stats=items=>`<div class="stat-grid">${items.map(([l,v,n,k=''])=>`<div class="stat ${k}"><span>${esc(l)}</span><strong>${esc(v)}</strong><small>${esc(n)}</small></div>`).join('')}</div>`;
const metric=(l,v,n)=>`<div class="metric"><span>${esc(l)}</span><strong>${esc(v)}</strong><small>${esc(n)}</small></div>`;
function lineChart(rows,key,label,scale=1){const valid=rows.filter(r=>typeof r[key]==='number'&&Number.isFinite(r[key]));if(!valid.length)return empty('공개된 월별 관측이 없습니다.');const w=800,h=230,L=55,R=18,T=18,B=38;let lo=Math.min(0,...valid.map(r=>r[key]*scale)),hi=Math.max(0,...valid.map(r=>r[key]*scale));if(lo===hi){lo-=.1;hi+=.1;}const gap=(hi-lo)*.15;lo-=gap;hi+=gap;const x=i=>L+(w-L-R)*i/Math.max(1,rows.length-1),y=v=>T+(hi-v)/(hi-lo)*(h-T-B);let path='',open=false;rows.forEach((r,i)=>{if(typeof r[key]==='number'){path+=`${open?'L':'M'}${x(i)},${y(r[key]*scale)} `;open=true;}else open=false;});return `<svg class="chart line-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}; ${rows[0].month}–${rows.at(-1).month} · ${valid.length}개 관측. 상세 표에서 수치를 확인할 수 있습니다.</title>${Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4).map(v=>`<line x1="${L}" y1="${y(v)}" x2="${w-R}" y2="${y(v)}" stroke="#e8edf3"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">${num(v,2)}</text>`).join('')}<line x1="${L}" y1="${y(0)}" x2="${w-R}" y2="${y(0)}" stroke="#97a5bb" stroke-dasharray="4 4"/><path d="${path}" fill="none" stroke="#466bce" stroke-width="2.3"/>${rows.map((r,i)=>typeof r[key]==='number'?`<circle cx="${x(i)}" cy="${y(r[key]*scale)}" r="3" fill="${r[key]<0?'#c28560':'#466bce'}"><title>${esc(r.month)}: ${num(r[key]*scale,4)}</title></circle>`:'').join('')}${[0,Math.floor(rows.length/3),Math.floor(rows.length*2/3),rows.length-1].map(i=>`<text x="${x(i)}" y="${h-8}" text-anchor="${i===0?'start':i===rows.length-1?'end':'middle'}">${esc(rows[i].month)}</text>`).join('')}</svg>`;}
function costChart(m){if(![m.gross,m.cost,m.net].every(v=>typeof v==='number'))return empty('같은 기간의 비용 전후 집계가 없습니다.');const rows=[['비용 전 초과수익',m.gross,'blue'],['모형 거래비용',m.cost,'amber'],['비용 후 초과수익',m.net,m.net<0?'red':'green']],max=Math.max(...rows.map(r=>Math.abs(r[1])),.001);return `<div class="cost-chart">${rows.map(([n,v,k])=>`<div class="cost-row"><span>${n}</span><div class="cost-track"><i class="${k}" style="width:${Math.abs(v)/max*100}%"></i></div><strong class="${k}-text">${sign(v)}<small> pp/년</small></strong></div>`).join('')}</div><p class="chart-note">Discovery 진단 · 월평균 × 12 · 같은 적격 유니버스 동일가중 수익 대비 초과수익 · KOSPI 비교·CAGR 아님. 비용은 차감 금액입니다.</p>`;}
function outcomes(){const c=window.ResearchSemantics.researchVerdictCounts(research.records),states=[['PROMOTE','blue','승격 통과'],['REJECT','slate','승격 탈락'],['PENDING','amber','검증 중']];return `<div class="outcome-bar" aria-label="공개 연구 판정 비중">${states.map(([s,k,l])=>`<div class="${k}" style="width:${research.records.length?c[s]/research.records.length*100:0}%" title="${l} ${c[s]}건"></div>`).join('')}</div><div class="legend">${states.map(([s,k,l])=>`<span><i class="${k}"></i>${l} <strong>${c[s]}</strong></span>`).join('')}</div><p class="chart-note">공개 연구만 집계합니다. 평가가 끝난 과거 PROVISIONAL 중 고유 예측력 검사 실패는 승격 탈락에 포함하며, 당시 판정은 상세에 보존합니다. 봉인·진행 중 비공개 기록은 별도입니다.</p>`;}
// Campaign date is the retained chronology, not the lesson review/completion timestamp.
function lessonResearchDate(r){
 const m=/^campaign-(\d{4})(\d{2})(\d{2})-\d+$/.exec(r.campaign_id||'');
 if(!m)return null;
 const iso=`${m[1]}-${m[2]}-${m[3]}`,time=Date.parse(`${iso}T00:00:00Z`);
 return Number.isFinite(time)&&new Date(time).toISOString().slice(0,10)===iso?iso:null;
}
function lessonSequence(r){
 const m=/^cycle-(\d+)(?:-|$)/.exec(r.provenance?.cycle||'');
 return m&&Number.isSafeInteger(Number(m[1]))?Number(m[1]):null;
}
function sortedLessons(records=research.records){
 return records.filter(reviewed).sort((a,b)=>{
  const ad=lessonResearchDate(a),bd=lessonResearchDate(b);
  if(ad!==bd)return ad===null?1:bd===null?-1:bd.localeCompare(ad);
  return (lessonSequence(b)??-1)-(lessonSequence(a)??-1)||String(b.record_id||'').localeCompare(String(a.record_id||''),'en',{numeric:true});
 });
}
function lessonChronology(r){
 const d=lessonResearchDate(r),sequence=lessonSequence(r);
 return `${d?`캠페인 <time datetime="${d}">${date(d)}</time>`:'캠페인 날짜 미확인'}${sequence!==null?` · 연구 #${sequence}`:''}`;
}
function lessonTitle(r){
 if(r.factor_name==='return_trading_activity_correlation_12m')return '순위 예측력, 원인, 구현 수익성은 서로 다른 질문입니다.';
 if(r.factor_name==='operating_asset_growth_12m')return '재무제표의 증가를 경제적 성장으로 바로 읽지 않습니다.';
 // Reuse the reviewed Korean sentence, without inventing a stronger claim or editing evidence.
 const first=String(r.review?.general_lesson||'').trim().split(/(?<=[.!?])\s+/)[0];
 return /[가-힣]/.test(first)?first:'이 연구에서 얻은 교훈';
}
const reviewLabels={UNCERTAIN:'교훈 판단 유보',SUPPORTS:'교훈과 부합',UNTESTED:'미검증',SUPPORTED:'관측 근거 있음',MIXED:'근거 혼재',NOT_SUPPORTED:'관측 근거가 지지하지 않음',ACCEPT:'검토 수용',REVISE:'수정 필요',REJECT:'검토 불수용'};
const reviewLabel=v=>reviewLabels[v]||'판정 미확인';
function lessonCard(r,compact=false){
 const heading=lessonTitle(r),body=String(r.review.general_lesson||'');
 const remainder=body.startsWith(heading)?body.slice(heading.length).trim():body;
 return `<article class="panel lesson-card"><div class="panel-top"><span class="eyebrow">팩터 연구에서 얻은 교훈</span>${badge('검토 완료','green')}</div><h3>${esc(heading)}</h3>${remainder?`<p class="lesson-text ${compact?'clamp':''}">${esc(remainder)}</p>`:''}<div class="origin"><small>이 교훈을 얻은 팩터 연구</small><strong>${esc(title(r.factor_name))}</strong><span>${lessonChronology(r)} · 연구 규칙 ${esc(r.ruleset)}</span><details class="lesson-identifiers"><summary>원본 연구 식별자</summary><code>${esc(r.factor_name)}</code><code>${esc(r.family)}</code><code>${esc(r.campaign_id)}</code><code>${esc(r.review.lesson_key)}</code></details></div><div class="panel-bottom">${researchVerdictBadge(r)}${badge(reviewLabel(r.review.stance||'UNCERTAIN'))}${recordLink(r,'근거와 해석 읽기')}</div></article>`;
}

function getRegimeStudy(){const studies=window.ResearchSemantics.selectStudies(research).regimeStudies;return studies.find(r=>r.record_id===ui.regimeStudy)||selectedRegimeStudy||null;}
function exposureNote(record,compact=false){
 const e=window.ResearchSemantics.campaignEvidence(research,record),reused=e.evidence_class==='HISTORICAL_REUSED_WINDOW';
 const text=reused?'과거 구간 재사용':e.evidence_class==='NOT_RECORDED'?'독립성·노출 기록 미연결':e.evidence_class;
 if(compact)return `<small class="muted block">${esc(text)}${e.prior_exposure_count!==null?` · 이전 노출 ${e.prior_exposure_count}건`:''}</small>`;
 return `<aside class="exposure-note"><strong>${esc(text)}${e.prior_exposure_count!==null?` · 등록된 이전 노출 ${e.prior_exposure_count}건`:''}</strong><p>확인 신호창 ${esc(e.signal_start||'미연결')} → ${esc(e.signal_end||'미연결')} · 수익 지원 ${esc(e.return_end||'미연결')}. ${e.evaluated?'이 사례의 확인 평가가 기록되어 있습니다.':'이 사례의 확인 평가 실행은 연결되지 않았습니다. 캠페인 기간과 실행 여부를 구분합니다.'}</p><p>이전 노출은 등록 메타데이터 건수이며 모든 비공식 열람을 센 값은 아닙니다. 캠페인 family 안의 BY 보정이 캠페인 간 적응적 표본 재사용 전체를 통제하지 않습니다.</p><details><summary>출처와 증거 분류</summary><code>${esc(e.campaign_id)} · ${esc(e.source_pointer||'NOT_RECORDED')} · ${esc(e.evidence_class)}</code></details></aside>`;
}
function goldExposureRecord(f){return {campaign_id:f.performance_basis?.campaign_id,validation:{confirmation_status:f.performance_basis?.confirmation_digest_verified?'EVALUATED':'NOT_EVALUATED'}};}
function regimeOverview(){const r=getRegimeStudy();if(!r)return empty('공개 기록에 레짐 진단이 수집된 연구가 없습니다. 최신 연구를 레짐 연구로 대신 표시하지 않습니다.');const g=r.regimes,summary=window.ResearchSemantics.reconcileCoarse(g);return `<section class="panel"><div class="panel-top"><p>${esc(title(r.factor_name))} · ${esc(g.phase||'단계 미수록')} ${g.monthly.length}신호월</p>${badge(g.input_status?.historical_pit_verified_for_all_inputs?'PIT_VERIFIED':'PIT_ASSUMED','amber')}</div>${coarseCards(g)}<p class="chart-note">UNKNOWN ${summary.unknown}개월 포함 ${summary.total}/${summary.monthly}개월 대사. 월말 t의 국면을 t+1 성과에 연결합니다. 12개월·3발생 구간은 설명 표시 정책이며 독립 재현이나 신뢰성의 보장선이 아닙니다.</p></section>`;}


function overview(){
 const c=research.counts,r=latestResearch;if(!r)return head('RESEARCH OVERVIEW','공개 연구 현황','공개 기록이 아직 없습니다.')+empty('봉인 기록을 대신 보여주지 않습니다.');
 const m=cm(r),d=dm(r),regimeStudies=window.ResearchSemantics.selectStudies(research).regimeStudies;
 return head('RESEARCH OVERVIEW','가설을 세우고,<br>근거로 남기는 연구.','승인 팩터, 실패한 가설, 검토된 교훈을 하나의 연구 지도에서 탐색합니다.',`<div class="edition">RESEARCH SNAPSHOT<br><strong>${date(research.as_of)}</strong></div>`)+freshness()+stats([
 ['현재 승인 집합',comparison?.factor_count??gold.approved_count,comparison?'DB 확인 · 성과는 과거 정의와 구분':'과거 스냅샷 · 현재 상태 미검증'],
 ['공개 연구 기록',c.released_records,`${c.campaigns_with_released_records}개 캠페인 · ${c.withheld_records}개 봉인·보류 별도`],
 ['검토 완료 교훈',c.reviewed_records,`${c.unreviewed_records}개 미검토 · 측정 완료 수와 다름`],
 ['레짐 진단 연구',regimeStudies.length,regimeStudies.length?`${getRegimeStudy().regimes.monthly.length}개 신호월 · 선택 연구 기준`:'진단 미수집','blue-stat']])+
 `<section class="featured"><div><span class="eyebrow">LATEST RESEARCH · ${esc(r.campaign_id.replace('campaign-',''))}</span><h2>${esc(title(r.factor_name))}</h2><p>${esc(r.definition.hypothesis||'가설 원문 미수록')}</p><button class="button" data-record="${esc(r.record_id)}">최신 연구 읽기 <span>↗</span></button></div><div class="feature-stats"><div><span>DISCOVERY RANK IC</span><strong>${num(d.ic_investable,4)}</strong><small>${period(r.performance.discovery?.discovery_signal_period)}</small></div><div><span>CONFIRMATION RANK IC</span><strong>${num(m.oos_ic,4)}</strong><small>${period({start:m.oos_start,end:m.oos_end})}${m.oos_months?` · ${m.oos_months}개월`:''}</small>${exposureNote(r,true)}</div><p>${researchVerdictBadge(r)} <span>연구 판정이며 Gold 적재 증거는 아닙니다.</span></p></div></section>`+
 `<div class="two-grid section-gap"><section class="panel"><div class="panel-top"><div><span class="eyebrow">RESEARCH OUTCOMES</span><h3>탈락한 연구도 자산입니다</h3></div><a class="text-button" href="#studies">전체 기록 ↗</a></div>${outcomes()}<div class="pair-summary"><div><strong>${window.ResearchSemantics.researchVerdictCounts(research.records).REJECT}</strong><span>탈락 기록</span></div><p>검사상 탈락 이유와 경제적 원인 추정을 구분합니다. 교훈 검토 완료와 직접 측정 완료는 다릅니다.</p></div></section><section class="panel"><div class="panel-top"><div><span class="eyebrow">IMPLEMENTATION GAP</span><h3>좋은 IC가 순수익을 보장하지는 않습니다</h3></div></div>${costChart(m)}</section></div>`+
 section('RECENT LESSONS','무엇을 배웠는가','<a class="text-button" href="#lessons">교훈 라이브러리 ↗</a>')+`<div class="two-grid">${sortedLessons().slice(0,4).map(r=>lessonCard(r,true)).join('')}</div>`+
 section('REGIME LENS','국면별 차이, 표본의 두께부터','<a class="text-button" href="#regimes">레짐 탐색 ↗</a>')+regimeOverview();
}
function lessons(){const rows=sortedLessons();return head('연구에서 얻은 교훈','결과를 넘어, 다음 연구의 교훈으로.','최신 연구부터 살펴봅니다. 캠페인 날짜 기준이며, 교훈 정리일·연구 완료시각과는 다릅니다.')+stats([['검토 완료',rows.length,'근거 해시 및 검토 결합 확인'],['미검토',research.counts.unreviewed_records,'검사 기록만 있으며 해석 미완료'],['레짐 연결 교훈',rows.filter(r=>Object.keys(r.regimes?.views||{}).length).length,'표본 부족·미관측 상태 포함'],['독립 재현','미확인','같은 과거 표본의 재사용을 구분']])+notice('<strong>검토 완료</strong>는 해석과 근거의 연결을 검토했다는 뜻입니다. 경제적 원인의 증명이나 독립 실증 재현을 의미하지 않습니다.','blue')+`<div class="toolbar section-gap"><label class="search"><span aria-hidden="true">⌕</span><input id="lesson-search" type="search" value="${esc(ui.lessonQuery||'')}" placeholder="팩터·교훈·가설 검색" aria-label="교훈 검색"></label></div><div id="lesson-results">${lessonResults()}</div>`+section('교훈 정리 과정','증거에서 교훈까지')+`<div class="process">${[['동결된 연구','가설·입력·기간을 먼저 고정'],['수치 증거','종료된 연구의 공개 근거 수집'],['해석과 경쟁 설명','관측 ID와 메커니즘 연결'],['별도 비평','과장·결측·사후 튜닝 점검'],['범위가 있는 교훈','근거 식별값과 한계를 함께 보존']].map(([t,p],i)=>`<div><b>0${i+1}</b><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`+section('전체 연구 기록','나머지 연구를 버리지 않습니다')+`<div class="panel"><h3>${research.counts.unreviewed_records?`${research.counts.unreviewed_records}개 기록은 아직 미검토입니다.`:'공개된 연구의 교훈 검토를 마쳤습니다.'}</h3><p>원래 가설, 검사 통과·탈락, 공개 가능한 성능을 연구 아카이브에서 확인할 수 있습니다. 자동 검사 사실과 경제적 해석은 구분됩니다.</p><a class="button secondary" href="#studies">전체 연구 아카이브 열기 ↗</a></div>`;}
const factorSortLabels={discovery_asc:'발견 순 · 오래된 순',discovery_desc:'발견 순 · 최근 순',name:'이름순 · 영문 ID'};
function discoveryDetail(f){const d=f.discovery||{};return section('DISCOVERY RECORD','발견 순서의 근거')+`<section class="panel"><h3>${discoveryTime(f)===null?'날짜 확인 불가':date(d.discovered_at)+' · 최초 연구 등록'}</h3><p>과거 승인 스냅샷 정의와 일치하는 가장 이른 보존 연구 기록입니다. 아이디어 탄생일, 승인일, 백테스트 시작일을 의미하지 않습니다.</p>${d.discovered_at?`<p>연구 #${esc(d.discovery_sequence)} · ${esc(d.campaign_id)} / ${esc(d.epoch_id)}</p>`:d.observed_name_first_registered_at?'<p>같은 이름의 과거 연구는 있지만 정의 해시가 달라 현재 승인 팩터의 날짜로 사용하지 않았습니다.</p>':'<p>연결 가능한 최초 연구 기록이 없습니다. 승인일로 대신 채우지 않습니다.</p>'}<details class="source"><summary>등록 시각 · 정의 연결 · 원본 출처</summary>${tree(d)}</details></section>`;}
function discoveryTime(f){const value=f.discovery?.discovered_at;return value&&Number.isFinite(Date.parse(value))?Date.parse(value):null;}
function compareFactors(a,b,sort=ui.factorSort){
 const byName=()=>a.name.localeCompare(b.name,'en');
 if(sort==='name')return byName();
 const at=discoveryTime(a),bt=discoveryTime(b);
 // Unknown dates stay last in both directions. Never substitute approval/sample dates.
 if(at===null||bt===null)return at===bt?byName():at===null?1:-1;
 const direction=sort==='discovery_desc'?-1:1;
 if(at!==bt)return direction*(at-bt);
 const as=a.discovery?.discovery_sequence,bs=b.discovery?.discovery_sequence;
 if(Number.isInteger(as)&&Number.isInteger(bs)&&as!==bs)return direction*(as-bs);
 return byName();
}
function filteredFactors(){const q=ui.factorQuery.trim().toLowerCase();return gold.factors.filter(f=>(ui.category==='ALL'||(f.category||'unknown')===ui.category)&&[f.name,title(f.name),f.hypothesis,f.meaning].join(' ').toLowerCase().includes(q)).sort(compareFactors);}
function discoveryCell(f){const d=f.discovery||{};return discoveryTime(f)===null?`${badge('확인 불가')}<small class="muted block">${d.observed_name_first_registered_at?'과거 정의 불일치':'연구 날짜 미연결'}</small>`:`<time datetime="${esc(d.discovered_at)}" title="최초 연구 등록 시각: ${esc(d.discovered_at)}">${date(d.discovered_at)}</time><small class="muted block">연구 #${esc(d.discovery_sequence??'—')} · KST</small>`;}
function factors(){
 const known=gold.factors.filter(f=>discoveryTime(f)!==null).length;
 return head('GOLD FACTOR CATALOG','승인 팩터의 의미와 성능.','아래 성과와 발견 순서는 과거 승인 스냅샷 기준입니다. 현재 승인 버전은 월초 실행 비교에서 별도로 확인하세요.')+freshness()+`<div class="toolbar wrap"><label class="search"><span aria-hidden="true">⌕</span><input id="factor-search" type="search" value="${esc(ui.factorQuery)}" placeholder="팩터 이름, 의미, 가설 검색" aria-label="승인 팩터 검색"></label><label class="select-label">정렬<select id="factor-sort">${Object.entries(factorSortLabels).map(([v,l])=>`<option value="${v}" ${ui.factorSort===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="select-label">분류<select id="factor-category"><option value="ALL">전체 분류</option>${[...new Set(gold.factors.map(f=>f.category||'unknown'))].sort().map(c=>`<option value="${esc(c)}" ${ui.category===c?'selected':''}>${esc(categories[c]||c)}</option>`).join('')}</select></label></div><p class="chart-note discovery-note">발견 순 = 과거 승인 스냅샷 정의와 일치하는 <strong>최초 연구 등록 시각</strong> 기준 · ${known}개 확인 / ${gold.factors.length-known}개 확인 불가. 같은 시각은 연구 시행 번호순, 날짜 미확인은 마지막에 표시합니다. 아이디어 탄생일·승인일·백테스트 시작일과는 다릅니다.</p><div id="factor-results">${factorResults()}</div><p class="chart-note">— 는 값이 없거나 기간·정의 연결을 확인하지 못한 경우입니다. 레거시 Sharpe와 Rank IC는 합산·순위화하지 않습니다.</p>`;
}
function factorResults(){const rows=filteredFactors();return `<div class="table-caption"><strong>${rows.length}개 팩터</strong><span>${factorSortLabels[ui.factorSort]||factorSortLabels.discovery_asc} · IC는 상관계수, 수익률이 아닙니다</span></div><div class="table-wrap"><table class="factor-table"><thead><tr><th>팩터 / 가설</th><th>발견 기록<br><small>최초 연구 등록</small></th><th>분류·방향</th><th>Discovery<br>Rank IC</th><th>OOS<br>Rank IC</th><th>비용 후 초과수익<br><small>Discovery · pp/년</small></th><th>검증 기준</th><th></th></tr></thead><tbody>${rows.map(f=>{const m=f.performance||{};return `<tr><td><button class="factor-name" data-factor="${esc(f.name)}">${esc(title(f.name))}</button><code>${esc(f.name)}</code><p class="table-hypothesis">${esc(f.hypothesis||'연결된 가설 자료 없음')}</p></td><td class="discovery-date">${discoveryCell(f)}</td><td>${badge(categories[f.category]||f.category||'미분류')}<small class="muted block">${f.predicted_sign===-1?'낮을수록 높은 점수':f.predicted_sign===1?'높을수록 높은 점수':'방향 미확인'}</small></td><td class="number">${num(m.ic_investable,4)}</td><td class="number">${num(m.oos_ic,4)}${exposureNote(goldExposureRecord(f),true)}</td><td class="number ${m.net<0?'red-text':''}">${sign(m.net)}</td><td><small>${esc(f.performance_basis?.rule||'미연결')}</small><small class="muted block">${m.oos_months?`${m.oos_months}개월 OOS`:'연결 성과 없음'}</small></td><td><button class="icon-button" data-factor="${esc(f.name)}" aria-label="${esc(f.name)} 상세">↗</button></td></tr>`}).join('')||`<tr><td colspan="8">${empty('검색어나 분류를 바꿔 주세요.')}</td></tr>`}</tbody></table></div>`;}
function studies(){return head('RESEARCH ARCHIVE','모든 공개 시행, 같은 기준으로.','성공한 가설만 남기지 않습니다. 원장 203건 중 공개 가능한 177건을 탐색합니다.')+`<div class="archive-summary">${outcomes()}</div><div class="toolbar wrap"><label class="search"><span>⌕</span><input id="study-search" type="search" value="${esc(ui.query)}" placeholder="팩터, 가설, 캠페인 검색" aria-label="연구 검색"></label><label class="select-label">판정<select id="study-verdict">${['ALL','PROMOTE','REJECT','PENDING'].map(v=>`<option ${ui.verdict===v?'selected':''} value="${v}">${({ALL:'전체 판정',PROMOTE:'승격 통과',REJECT:'승격 탈락',PENDING:'검증 중'})[v]}</option>`).join('')}</select></label><label class="select-label">검토<select id="study-review">${[['ALL','전체'],['REVIEWED','검토 완료'],['UNREVIEWED','미검토']].map(([v,l])=>`<option value="${v}" ${ui.review===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="select-label">계열<select id="study-family"><option value="ALL">전체 계열</option>${[...new Set(research.records.map(r=>r.family))].sort().map(v=>`<option value="${esc(v)}" ${ui.family===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div><div id="study-results">${studyResults()}</div>${notice(`${research.counts.withheld_records}건은 봉인 또는 진행 중이므로 성과·상세 내용을 포함하지 않습니다. PROMOTE는 연구 판정이며 Gold 승인 여부는 별도로 확인합니다.`,'blue')}`;}
function filteredStudies(){const q=ui.query.trim().toLowerCase();return [...research.records].reverse().filter(r=>(ui.verdict==='ALL'||window.ResearchSemantics.researchVerdict(r).code===ui.verdict)&&(ui.family==='ALL'||r.family===ui.family)&&(ui.review==='ALL'||(ui.review==='REVIEWED'?reviewed(r):!reviewed(r)))&&[r.factor_name,title(r.factor_name),r.campaign_id,r.definition.hypothesis].join(' ').toLowerCase().includes(q));}
function studyResults(){const rows=filteredStudies(),size=15,pages=Math.max(1,Math.ceil(rows.length/size));ui.page=Math.min(ui.page,pages);return `<div class="table-caption"><strong>${rows.length}개 연구 기록</strong><span>최근 캠페인순 · 별도 시행 보존</span></div><div class="table-wrap"><table><thead><tr><th>팩터 연구</th><th>원래 캠페인</th><th>판정</th><th>Discovery IC</th><th>OOS IC</th><th>교훈</th></tr></thead><tbody>${rows.slice((ui.page-1)*size,ui.page*size).map(r=>`<tr><td><button class="factor-name" data-record="${esc(r.record_id)}">${esc(title(r.factor_name))}</button><code>${esc(r.factor_name)}</code><small class="muted">${esc(r.family)}</small></td><td><small>${esc(r.campaign_id.replace('campaign-',''))}<br>${esc(r.epoch_id)} · ${esc(r.ruleset)}</small></td><td>${researchVerdictBadge(r)}</td><td class="number">${num(dm(r).ic_investable,4)}</td><td class="number">${num(cm(r).oos_ic,4)}</td><td>${badge(reviewed(r)?'검토 완료':'미검토',reviewed(r)?'green':'neutral')}</td></tr>`).join('')||`<tr><td colspan="6">${empty('조건에 맞는 공개 연구가 없습니다.')}</td></tr>`}</tbody></table></div><div class="pagination"><span aria-live="polite">${rows.length?`${(ui.page-1)*size+1}–${Math.min(ui.page*size,rows.length)}`:'0'} / ${rows.length}</span><div><button class="small-button" data-page="${ui.page-1}" ${ui.page===1?'disabled':''}>← 이전</button><span>${ui.page} / ${pages}</span><button class="small-button" data-page="${ui.page+1}" ${ui.page===pages?'disabled':''}>다음 →</button></div></div>`;}
function coarseRows(g){return window.ResearchSemantics.coarseRows(g);}
function coarseCards(g){return `<div class="regime-cards">${coarseRows(g).map(r=>`<div class="regime-tile ${r.support!=='DESCRIPTIVE_SUPPORT_ONLY'?'insufficient':''}"><span style="color:${color(r.regime)}">${esc(stateLabel(r.regime))}</span><strong>${num(r.rank_ic?.mean,4)}</strong><small>Rank IC · ${r.n_months}개월 / ${r.n_joint_usable_episodes??'미집계'}구간</small><em>${r.n_months===0?'미관측':r.support==='DESCRIPTIVE_SUPPORT_ONLY'?'설명 표본 요건 충족':'표본 부족'}</em></div>`).join('')}</div>`;}
function regimes(){const studies=window.ResearchSemantics.selectStudies(research).regimeStudies,r=getRegimeStudy();if(!r)return head('REGIME EXPLORER','레짐 진단 현황','공개된 레짐 연구가 없습니다.')+inputReadiness()+empty('최신 일반 연구를 레짐 진단으로 대신 사용하지 않습니다.');return head('REGIME EXPLORER','같은 팩터, 서로 다른 환경.','국면의 평균만 보지 않고 지속 기간, 발생 구간과 불확실성을 함께 읽습니다.')+`<div class="study-strip"><div><span class="eyebrow">CURRENT REGIME STUDY</span><strong>${esc(title(r.factor_name))}</strong><small>${esc(r.campaign_id)} · Discovery ${period(r.performance.discovery.discovery_signal_period)}</small></div>${recordLink(r,'원래 연구')}</div>`+inputReadiness()+notice(`상세 레짐 진단이 수집된 연구는 <strong>${studies.length}건</strong>입니다. 과거 모든 승인 팩터에 대한 검증으로 일반화할 수 없습니다. 선택된 동결 진단 단계는 <strong>${esc(r.regimes.phase||'미수록')}</strong>입니다. 별도 OOS 레짐 진단으로 전용하지 않습니다.`,'blue')+`<div class="toolbar wrap"><label class="select-label grow">연구 선택<select id="regime-study">${studies.map(x=>`<option value="${esc(x.record_id)}" ${x.record_id===r.record_id?'selected':''}>${esc(title(x.factor_name))} · ${x.regimes.monthly.length}신호월</option>`).join('')}</select></label><label class="select-label grow">분석 축<select id="regime-axis"><optgroup label="KOSPI 시장 국면">${Object.entries(axes).map(([k,v])=>`<option value="${k}" ${ui.axis===k?'selected':''}>${esc(v)}</option>`).join('')}</optgroup><optgroup label="정책·매크로 및 글로벌 보조지표">${Object.keys(r.regimes.macro_views||{}).sort((a,b)=>a==='KR_POLICY_DIRECTION_3M'?-1:b==='KR_POLICY_DIRECTION_3M'?1:a.localeCompare(b)).map(id=>`<option value="${esc(id)}" ${ui.axis===id?'selected':''}>${esc(macroLabel(id))}</option>`).join('')}</optgroup></select></label><div class="segmented" role="group" aria-label="레짐 성과 지표"><button data-metric="rank_ic" class="${ui.metric==='rank_ic'?'active':''}" aria-pressed="${ui.metric==='rank_ic'}">Rank IC</button><button data-metric="top_minus_bottom" class="${ui.metric==='top_minus_bottom'?'active':''}" aria-pressed="${ui.metric==='top_minus_bottom'}">상위−하위 수익</button></div></div><div id="regime-results">${regimeResults()}</div>`+section('READ THE CLASSIFICATION','월 리밸런싱 연구에서 읽는 방법')+`<div class="three-grid">${[['01 / TIME','완료된 월말 t','당시 가용하다고 간주한 입력으로 상태를 읽고 t+1 수익에 연결합니다. 월중 판독이나 미래 성과 기반 분류가 아닙니다.'],['02 / SAMPLE','12개월 + 3발생 구간','IC·수익이 함께 있는 달 12개와 떨어진 발생 구간 3개가 필요합니다. 이 조건은 설명 표시 정책이며 승격 gate·독립 재현·신뢰성 보장 요건이 아닙니다.'],['03 / LIMIT','설명이지 매매 스위치가 아닙니다','유리한 국면을 고른 사후 전략은 검증하지 않았습니다. HIGH/LOW는 각 지표 규칙에 따른 상대 상태입니다.']].map(([a,b,c])=>`<div class="panel"><span class="step">${a}</span><h3>${b}</h3><p>${c}</p></div>`).join('')}</div>`;}
function currentRegime(){const g=(getRegimeStudy()?.regimes||{}),macro=g.macro_views?.[ui.axis];let rows,monthly,pit;if(macro){rows=macro.states.map(r=>({...r,label:r.state}));monthly=macro.monthly_states.map(s=>({...g.monthly.find(m=>m.month===s.month),...s,label:s.state}));pit=macro.pit_status||(ui.axis==='KR_POLICY_DIRECTION_3M'?'VERIFIED_INPUT':'PIT_ASSUMED');}else{rows=(ui.axis==='regime'?coarseRows(g):g.views?.[ui.axis]||[]).map(r=>({...r,label:r[ui.axis]}));monthly=(g.monthly||[]).map(r=>({...r,label:r[ui.axis]}));pit='PIT_ASSUMED';}return {g,macro,rows,monthly,pit};}
function forest(rows,key){const scale=key==='rank_ic'?1:100,vals=rows.flatMap(r=>[r[key]?.mean,...(r[key]?.ci95||[])]).filter(v=>typeof v==='number').map(v=>v*scale);let lo=Math.min(0,...vals),hi=Math.max(0,...vals);if(lo===hi)hi=1;const extra=(hi-lo)*.12;lo-=extra;hi+=extra;const w=800,rh=ui.axis==='regime_detail'?43:56,h=rows.length*rh+50,L=ui.axis==='regime_detail'?340:150,R=100,x=v=>L+(v-lo)/(hi-lo)*(w-L-R);return `<svg class="chart forest" role="img" viewBox="0 0 ${w} ${h}" aria-label="국면별 평균과 95% HAC 구간"><title>국면별 평균과 95% HAC 구간. 표본 부족은 구간 미산출. 정확한 수치는 아래 표에 있습니다.</title><line x1="${x(0)}" y1="10" x2="${x(0)}" y2="${h-35}" stroke="#afbcca" stroke-dasharray="4 4"/>${rows.map((r,i)=>{const y=28+i*rh,v=r[key]?.mean,ci=r[key]?.ci95,ok=r.support==='DESCRIPTIVE_SUPPORT_ONLY';return `<text x="4" y="${y+5}" class="${ui.axis==='regime_detail'?'small-axis':''}">${esc(ui.axis==='regime_detail'?r.label:stateLabel(r.label))}</text><line x1="${L}" y1="${y}" x2="${w-R}" y2="${y}" stroke="#edf0f5"/>${typeof v==='number'?`${ci?`<line x1="${x(ci[0]*scale)}" y1="${y}" x2="${x(ci[1]*scale)}" y2="${y}" stroke="#7f9ade" stroke-width="3"/>`:''}<circle cx="${x(v*scale)}" cy="${y}" r="5" fill="${ok?'#426bd1':'white'}" stroke="${ok?'#426bd1':'#c48d55'}" stroke-width="2"/>`:''}<text x="${w-5}" y="${y+5}" text-anchor="end">${num(typeof v==='number'?v*scale:null,key==='rank_ic'?4:2)}</text>`}).join('')}${[lo,(lo+hi)/2,hi].map(v=>`<text x="${x(v)}" y="${h-5}" text-anchor="middle">${num(v,key==='rank_ic'?3:2)}</text>`).join('')}</svg>`;}
function regimeResults(){const {g,macro,rows,monthly,pit}=currentRegime(),k=ui.metric,scale=k==='rank_ic'?1:100,support=rows.filter(r=>r.support==='DESCRIPTIVE_SUPPORT_ONLY').length;return `<div class="two-grid regime-layout"><section class="panel"><div class="panel-top"><div><span class="eyebrow">STATE COMPARISON</span><h3>${esc(axes[ui.axis]||macroLabel(ui.axis))}</h3></div>${badge(pit,pit==='PIT_ASSUMED'?'amber':'green')}</div><p class="chart-note">${k==='rank_ic'?'순위 상관계수 · 무차원':'월평균 상위−하위 그룹 수익 차이 · %p/월 · 비용 미반영'}</p>${forest(rows,k)}<div class="legend"><span><i class="blue"></i>평균 · 선은 상태별 서술용 95% HAC 근사구간</span><span><i class="outline"></i>표본 부족 · 구간 미산출</span></div></section><aside class="panel reading-panel"><span class="eyebrow">READ WITH CONTEXT</span><h3>숫자 옆의 조건</h3><div class="read-metric"><strong>${support}<small> / ${rows.length}</small></strong><span>상태별 설명 표본 요건 충족<br>UNKNOWN 포함 전체 상태 기준</span></div><p>${macro?'지표의 분류 규칙을 확인하세요. 선물 관련 축은 현물 가격이 아닌 COT 포지셔닝일 수 있습니다.':'장기·단기 추세와 변동성을 별도로 읽습니다. LOW가 절대적으로 안전함을 뜻하지 않습니다.'}</p><hr><h4>${pit==='PIT_ASSUMED'?'사용자가 수용한 PIT 가정':'발표일 기반 검증 입력'}</h4><p>${pit==='PIT_ASSUMED'?'과거 최초값·가용시각은 근사입니다. 실제 수집 시각을 보존하고 보조 진단으로만 사용합니다. 최초 발표본 인증이 아닙니다.':'공식 정책 결정 발표일 종료를 보수적 가용 상한으로 사용합니다. 정확한 장중 시각 인증은 아닙니다.'}</p><hr><p>구간은 각 상태별(pointwise) 서술용 HAC 근사치입니다. 상태 간 차이 검정·동시 신뢰구간·다중 진단 보정은 제공되지 않았습니다. 높은 평균 하나로 보편성을 주장하지 않습니다.</p></aside></div><section class="panel section-gap"><div class="panel-top"><div><span class="eyebrow">MONTHLY CONTEXT</span><h3>국면과 성과의 시간축</h3></div><span class="meta">신호월 t → 다음 달 성과</span></div><div class="month-ribbon" aria-label="월별 국면">${monthly.map(r=>`<div style="background:${color(r.label||'UNKNOWN')}" title="${esc(r.month)} → ${esc(r.effective_month)}: ${esc(stateLabel(r.label))}" tabindex="0"><span>${esc(r.month)}<br>${esc(stateLabel(r.label))}</span></div>`).join('')}</div>${lineChart(monthly,k,`월별 ${k}`,scale)}<p class="chart-note">설명용 그룹을 매월 재구성한 진단입니다. 실현 보유전략의 손익곡선이나 누적 수익률이 아닙니다.</p><details class="source"><summary>월별 상태와 정확한 수치 (${monthly.length}개월)</summary>${monthlyTable(monthly,true)}</details></section>`+section('SAMPLE & UNCERTAINTY','모든 상태를 그대로 보존합니다')+`<div class="table-wrap"><table><thead><tr><th>국면</th><th>관측 개월</th><th>공동 유효 개월</th><th>발생 구간</th><th>평균 ${k==='rank_ic'?'IC':'차이 (%p/월)'}</th><th>95% 구간</th><th>표본 상태</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(stateLabel(r.label))}</td><td class="number">${r.n_months}</td><td class="number">${r.n_joint_usable_months??'—'}</td><td class="number">${r.n_joint_usable_episodes??'—'}</td><td class="number">${num(typeof r[k]?.mean==='number'?r[k].mean*scale:null,4)}</td><td class="number">${r[k]?.ci95?.map(v=>num(v*scale,4)).join(' ~ ')||'미산출'}</td><td>${badge(r.support==='DESCRIPTIVE_SUPPORT_ONLY'?'설명 표본 충족':r.support==='UNKNOWN_CONTEXT'?'미분류':'표본 부족',r.support==='DESCRIPTIVE_SUPPORT_ONLY'?'blue':'amber')}</td></tr>`).join('')}</tbody></table></div><details class="source"><summary>분류 규칙 · 출처 · 적용 범위</summary>${tree(macro?{classification_rules:macro.classification_rules,source_id:macro.source_id,scope:macro.scope,known_at_semantics:macro.known_at_semantics,assumptions:macro.assumptions,rules_sha256:macro.rules_sha256}:g.classification_rules)}</details>`;}
function monthlyTable(rows,regime=false){return `<div class="table-wrap"><table><thead><tr><th>신호월</th>${regime?'<th>수익월</th><th>국면</th>':''}<th>Rank IC</th><th>상위−하위 (%p/월)</th><th>유효 종목 쌍</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.month)}</td>${regime?`<td>${esc(r.effective_month)}</td><td>${esc(stateLabel(r.label))}</td>`:''}<td class="number">${num(r.rank_ic,4)}</td><td class="number">${sign(typeof r.top_minus_bottom==='number'?r.top_minus_bottom*100:null,3)}</td><td class="number">${num(r.n_pairs,0)}</td></tr>`).join('')}</tbody></table></div>`;}
function keyLabel(k){return ({hypothesis:'가설',mechanism:'메커니즘 가정',reason:'판단 근거',claim:'주장',assessment:'판정',evidence_ids:'근거 ID',status:'상태',scope:'적용 범위',mean:'평균',n_months:'관측 개월',ci95:'95% 구간',notes:'참고',limitations:'한계',data:'관측 자료',definition:'정의',source_id:'데이터 출처',classification_rules:'분류 규칙',assumptions:'수용 가정',predicted_sign:'사전 방향',rebalance_months:'리밸런싱 주기 (월)',inputs:'입력',params:'고정 파라미터',falsification:'반증 조건',data_notes:'데이터 유의점',follow_up:'후속 제안 (미실행)'})[k]||human(k);}
function tree(v,depth=0){if(v===null||v===undefined)return '<span class="muted">미수집 / null</span>';if(typeof v!=='object')return `<span class="raw-value">${esc(v)}</span>`;if(Array.isArray(v)){if(!v.length)return '<span class="muted">항목 없음</span>';if(v.every(x=>typeof x!=='object'))return `<ul class="prose-list">${v.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;return `<div class="object-list">${v.map((x,i)=>`<details ${depth===0?'open':''}><summary>${esc(x?.name||x?.id||x?.link||x?.month||x?.section||`항목 ${i+1}`)}</summary>${tree(x,depth+1)}</details>`).join('')}</div>`;}return `<dl class="data-dl">${Object.entries(v).map(([k,x])=>`<dt>${esc(keyLabel(k))}</dt><dd>${typeof x==='object'&&x!==null?`<details ${depth<1?'open':''}><summary>${Array.isArray(x)?`${x.length}개 항목`:'상세 값'}</summary>${tree(x,depth+1)}</details>`:tree(x,depth+1)}</dd>`).join('')}</dl>`;}
function methodInputStatus(){const r=getRegimeStudy();if(!r)return empty('공개된 레짐 연구가 없어 동결 입력 수를 표시하지 않습니다.');const input=r.regimes.input_status||{},verified=Array.isArray(input.verified_context_ids)?input.verified_context_ids:null,assumed=Array.isArray(input.assumed_context_ids)?input.assumed_context_ids:null;return `<p class="chart-note">선택한 동결 연구: ${esc(title(r.factor_name))}. 현재 원천 준비 현황과는 별개입니다.</p><div class="three-grid"><article class="panel"><h3>검증 분류 입력 ${verified?verified.length+'축':'목록 미수록'}</h3>${badge(verified?.length?'VERIFIED_INPUT':'검증 목록 미확인',verified?.length?'green':'neutral')}<p>원문에서 검증된 입력으로 분류한 목록입니다. 입력별 가용시각·계약 범위는 원래 증거에 따르며 실제 장중 체결의 인증이 아닙니다.</p><p>${verified===null?'목록 미수록을 입력이 없다는 뜻으로 해석하지 않습니다.':verified.length?verified.map(x=>esc(macroLabel(x))).join(' · '):'원문에 수록된 검증 분류 목록은 비어 있습니다.'}</p></article><article class="panel"><h3>가정 입력 ${assumed?assumed.length+'축':'목록 미수록'}</h3>${badge(assumed?.length?'PIT_ASSUMED':'가정 목록 미확인',assumed?.length?'amber':'neutral')}<p>수용된 역사적 값·시각 근사의 범위입니다. 실제 receipt와 원래 계약을 보존하며 최초 발표본 인증으로 바꾸지 않습니다. 새 방향 입력과 최신 준비 상태는 레짐 화면에서 별도로 봅니다.</p></article><article class="panel"><h3>진단 범위</h3>${badge('DIAGNOSTIC ONLY','blue')}<p>레짐 보조 설명에 한정됩니다. 팩터 feature 계약·승격 기준 완화나 사후 최적화에 사용하지 않습니다.</p>${recordLink(r,'원래 연구의 입력 계약')}</article></div>`;}
function method(){return head('EVIDENCE & METHOD','대시보드를 읽는 기준.','수치가 답하는 질문과 근거의 경계를 먼저 확인합니다.')+freshness()+`<div class="two-grid section-gap"><section class="panel"><span class="eyebrow">TWO DIFFERENT STATES</span><h3>연구 PROMOTE ≠ 운영 APPROVED</h3><p>PROMOTE는 고정 연구 검사의 결과입니다. Gold SQL parity, 게시와 승인은 별도의 증거로 확인해야 합니다. 이 사이트는 팩터를 승인하거나 적재하지 않습니다.</p><p>Gold 집합에는 레거시 팩터도 있습니다. 공개 연구 원장과 일대일 관계가 아니므로 두 숫자를 빼서 미적재 수로 해석하지 않습니다.</p></section><section class="panel"><span class="eyebrow">SNAPSHOT, NOT A LIVE FEED</span><h3>원본을 바꾸지 않는 읽기 전용 뷰</h3><p>연구 내보내기: ${date(research.as_of)}<br>Gold 근거 기준: ${date(gold.catalog_as_of||gold.as_of)}<br>새 연구·DB 변경은 자동 반영되지 않습니다.</p><p>종료·공개 허용 상태, 근거 hash와 검토 결합을 확인해 내보냅니다. 봉인 기록의 성능은 포함하지 않습니다.</p></section></div>`+section('METRIC DICTIONARY','성능 지표를 혼동하지 않기')+`<div class="table-wrap"><table><thead><tr><th>지표</th><th>어떤 질문인가</th><th>단위와 한계</th></tr></thead><tbody>${[['Rank IC','점수 순위가 다음 달 수익률 순위와 연결되는가?','월별 Spearman 상관의 평균. 무차원이며 수익률 %가 아님.'],['Rank ICIR','월별 순위 관계가 얼마나 안정적인가?','월평균 IC ÷ 월별 IC 표준편차. 비연율화.'],['비용 전 / 후 초과수익','고정 규칙과 비용모형에서 벤치마크를 초과하는가?','Discovery 월평균 × 12, %p/년. CAGR·OOS 순수익·실체결 수익이 아님.'],['Net IR','초과수익 변동성 대비 보상이 있는가?','연율화 초과수익 정보비율. Sharpe와 다름.'],['국면별 상위−하위','점수 그룹의 평균 수익 차이는?','매월 재구성 동일가중 그룹, %p/월. 비용 미반영. 실행된 롱숏 전략 아님.'],['95% HAC 구간','평균이 얼마나 불확실한가?','월별 관측 기반. 표본 충족 시만 산출. 국면 차이 검정·인과 증명 아님.']].map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`+section('POINT IN TIME','PIT는 표시를 없애는 방식으로 해결하지 않습니다')+methodInputStatus()+section('RELEASE & AUDIT','공개 경계와 재현 가능성')+`<section class="panel"><p>원장 ${research.counts.ledger_records}건 중 ${research.counts.released_records}건 공개, ${research.counts.withheld_records}건 보류. 교훈 ${research.counts.reviewed_records}건 검토. 과거 구간 재사용은 독립 미래 검증이 아닙니다.</p><p>연구 결과 해석자용입니다. 새 후보 생성자에게 상세 OOS 수치·성과 순위를 전달하는 자료로 사용하지 않습니다.</p><div class="download-row"><a class="small-button" href="./data/research-catalog.json" download>공개 연구 스냅샷 JSON ↓</a><a class="small-button" href="./data/gold-catalog.json" download>Gold 근거 스냅샷 JSON ↓</a></div><details class="source"><summary>내보내기 한계와 원본 기준</summary>${tree({research_source:research.source,research_limitations:research.limitations,gold_source:gold.source,gold_limitations:gold.limitations})}</details></section>`;}
const detailHead=(k,t,s)=>`<div class="dialog-head"><div><span class="eyebrow">${esc(k)}</span><h2 id="detail-title">${esc(t)}</h2><code>${esc(s)}</code></div><button class="icon-button close" data-close aria-label="상세 창 닫기">×</button></div>`;
function showDialog(html){$('#detail-content').innerHTML=html.replace('<div class="dialog-body">','<div class="dialog-body">'+comparisonBanner());const d=$('#detail-dialog');if(!d.open)d.showModal();d.scrollTop=0;}
function openFactor(name){const f=gold.factors.find(x=>x.name===name);if(!f)return;const m=f.performance||{},p=f.performance_basis?.period||{},linked=research.records.filter(r=>r.factor_name===name);showDialog(detailHead('GOLD FACTOR',title(name),name)+`<div class="dialog-body"><div class="badge-row">${statusBadge('APPROVED')}${badge(gold.is_live?'DB 확인':'과거 집합 · 현재 미검증',gold.is_live?'green':'amber')}${badge(categories[f.category]||f.category||'미분류')}</div><section class="hypothesis"><span class="eyebrow">WHAT THIS FACTOR MEASURES</span><h3>${esc(f.meaning||'연결된 정의 자료 없음')}</h3><p>${esc(f.hypothesis||'연결된 사전 가설 자료가 없습니다. 이름만으로 가설을 만들어 넣지 않았습니다.')}</p></section><div class="two-grid"><div class="panel"><h4>점수의 방향</h4><p>${f.predicted_sign===-1?'원시 값이 낮을수록 높은 점수':f.predicted_sign===1?'원시 값이 높을수록 높은 점수':'미확인'}</p><p>리밸런싱: ${f.rebalance_months?`${f.rebalance_months}개월`:'미확인'}</p></div><div class="panel"><h4>해석의 한계</h4><p>가설은 검증된 경제적 원인이 아닙니다. ${esc(f.definition_binding||'정의 결합 자료 없음')}</p></div></div>`+discoveryDetail(f)+section('PERFORMANCE','기간을 함께 읽는 성능')+`<div class="metric-grid">${metric('Discovery IC',num(m.ic_investable,4),`${p.discovery_signal_start||'?'} → ${p.discovery_signal_end||'?'}`)}${metric('OOS IC',num(m.oos_ic,4),`${p.oos_signal_start||m.oos_start||'?'} → ${p.oos_signal_end||m.oos_end||'?'}`)}${metric('Rank ICIR',num(m.rank_icir_investable),'비연율화 · Discovery')}${metric('Net IR',num(m.net_ir),'연율화 · Discovery')}</div>${exposureNote(goldExposureRecord(f))}${costChart(m)}<p class="chart-note">${esc(f.performance_basis?.rule||'규칙 미확인')} · ${esc(f.performance_basis?.evidence_class||'증거 분류 미확인')} · 기간·규칙이 다른 성과를 직접 순위화하지 않습니다.</p>`+section('LINKED RESEARCH','이 팩터를 연구한 기록')+`${linked.length?linked.map(r=>`<div class="linked-row"><span>${esc(r.campaign_id)} · ${researchVerdictBadge(r)}</span>${recordLink(r)}</div>`).join(''):notice('공개 연구 원장에 연결된 연구가 없습니다. 레거시 또는 미연결일 수 있으며 성과가 없다는 뜻은 아닙니다.','blue')}<details class="source"><summary>정의 · 기간 · 단위 · 출처 전체</summary>${tree(f)}</details></div>`);}
function reviewSection(r){const v=r.review,links={measurement:'측정',economic_change:'경제적 변화',price_response:'가격 반영',implementation:'구현'};return section('검토 완료 교훈','이 연구에서 얻은 교훈')+`<section class="lesson-callout"><h3>${esc(lessonTitle(r))}</h3><p>${esc(v.general_lesson)}</p><p>${esc(v.economic_interpretation)}</p><div class="badge-row">${badge(reviewLabel(v.stance||'UNCERTAIN'),'blue')}${badge(`비평: ${v.critic?.decision?reviewLabel(v.critic.decision):'미연결'}`,'green')}${badge('독립 재현 미확인','amber')}</div></section><h3 class="section-gap">메커니즘의 연결고리별 판정</h3><div class="mechanism-grid">${(v.mechanism_assessment||[]).map((x,i)=>`<article><span class="step">0${i+1} / ${esc(links[x.link]||x.link)}</span>${badge(reviewLabel(x.assessment),({SUPPORTED:'green',NOT_SUPPORTED:'red',MIXED:'amber'})[x.assessment]||'neutral')}<p>${esc(x.reason||(x.assessment==='UNTESTED'?'이 연결을 판단할 세부 근거가 수집되지 않았습니다.':'아래 관측과 근거 ID에서 판정 범위를 확인하세요.'))}</p></article>`).join('')}</div><details class="source" open><summary>실제로 관측한 것 ${(v.observations||[]).length}개</summary><ol class="observations">${(v.observations||[]).map(x=>`<li><p>${esc(x.text)}</p><div class="evidence-ids">${(x.evidence_ids||[]).map(id=>`<code>${esc(id)}</code>`).join('')}</div></li>`).join('')}</ol></details><div class="two-grid section-gap"><section class="panel"><h3>다른 설명도 가능합니다</h3><ul class="prose-list">${(v.alternative_explanations||[]).map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul></section><section class="panel"><h3>이 교훈의 적용 범위</h3><p>${esc(v.scope)}</p><h4>해결되지 않은 질문</h4><ul class="prose-list">${(v.unresolved||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section></div><details class="source"><summary>누락 근거 · 후속 제안 · 비평 전체</summary>${tree({lesson_key:v.lesson_key,missing_evidence:v.missing_evidence,follow_up:v.follow_up,critic:v.critic,visual_inspection:v.visual_inspection,explanations:v.explanations})}</details>`;}
function openRecord(id){const r=research.records.find(x=>x.record_id===id);if(!r)return;const d=dm(r),m=cm(r),p=r.performance.discovery?.discovery_signal_period,rows=r.diagnostics?.monthly_performance?.data?.monthly;showDialog(detailHead('RESEARCH RECORD',title(r.factor_name),r.record_id)+`<div class="dialog-body"><div class="badge-row">${researchVerdictBadge(r)}${badge(reviewed(r)?'교훈 검토 완료':'교훈 미검토',reviewed(r)?'green':'neutral')}${badge(r.ruleset)}</div>${researchVerdictDetail(r)}<section class="hypothesis"><span class="eyebrow">PREREGISTERED HYPOTHESIS</span><h3>${esc(r.definition.hypothesis||r.definition.calculation_summary||'연결된 가설 없음')}</h3><p>${esc(r.definition.mechanism||'메커니즘 설명 미수록')}</p></section><div class="two-grid"><div class="panel"><h4>사전 정의</h4><p>${esc(r.definition.calculation_summary||r.definition.hypothesis)}</p><p>방향: ${r.definition.predicted_sign===-1?'낮은 원시 값 우대':r.definition.predicted_sign===1?'높은 원시 값 우대':'미확인'} · 리밸런싱 ${r.definition.rebalance_months||'?'}개월</p></div><div class="panel"><h4>반증 조건</h4><p>${esc(r.definition.falsification||'원문에 별도 반증 조건이 없습니다.')}</p></div></div>`+section('FROZEN EVALUATION','연구 과정과 결과')+`<div class="research-timeline"><div><span>DISCOVERY</span><strong>${period(p)}</strong><small>고정 과거 탐색 표본</small></div><div class="embargo"><span>EMBARGO</span><strong>분리</strong><small>표본 경계 보존</small></div><div><span>CONFIRMATION</span><strong>${m.oos_start&&m.oos_end?`${m.oos_start} → ${m.oos_end}`:'미실행 / 연결 없음'}</strong><small>${m.oos_months?`${m.oos_months}개월 · 과거 표본 재사용`:'미실행은 미검증'}</small></div></div><div class="metric-grid">${metric('Discovery IC',num(d.ic_investable,4),'투자가능 표본')}${metric('OOS IC',num(m.oos_ic,4),'캠페인 내 1회 · 표본 재사용 이력 별도')}${metric('중립화 IC',num(m.neutral_ic??d.neutral_ic,4),'연구 gate의 노출 제거')}${metric('Gold 최대 상관',num(m.max_gold_signal_corr??d.max_gold_signal_corr,4),'인과적 독립성의 증명 아님')}</div>${exposureNote(r)}${costChart(m)}${notice('Confirmation 파일의 gross·cost·net도 Discovery 기간의 포트폴리오 진단입니다. OOS IC와 OOS 순수익을 혼동하지 않습니다. 과거 표본 재사용은 독립 미래 검증이 아닙니다.','blue')}${reviewed(r)?reviewSection(r):`<section class="panel section-gap"><h3>교훈은 아직 검토되지 않았습니다.</h3><p>${esc(r.unreviewed_notice||'자동 검사 사실만 보존되어 있습니다. 통과·실패만으로 경제적 원인을 추정하지 않습니다.')}</p></section>`}`+section('MONTHLY EVIDENCE','월별 관측과 진단')+`${rows?.length?`<section class="panel"><h3>월별 Rank IC</h3>${lineChart(rows,'rank_ic','Discovery 월별 Rank IC')}<p class="chart-note">설명용 월별 점수와 다음 달 수익의 관계. 위 중립화 IC는 gate 값이며 별도 공통표본 통제 진단과 다를 수 있습니다.</p><details class="source"><summary>월별 숫자표 ${rows.length}개월</summary>${monthlyTable(rows)}</details></section>`:empty('월별 진단이 수집되지 않았습니다. 미수집을 0으로 채우지 않습니다.')}`+section('CHECKS','어떤 검사를 통과하거나 탈락했나')+`<details class="source"><summary>단계별 전체 검사 열기</summary>${['discovery','confirmation'].filter(phase=>r.performance[phase]).map(phase=>`<h3>${phase==='discovery'?'Discovery':'Confirmation'}</h3><div class="table-wrap"><table><thead><tr><th>검사</th><th>상태</th><th>관측 값</th><th>고정 기준</th></tr></thead><tbody>${(r.performance[phase].checks||[]).map(c=>`<tr><td><small>${esc(c.tier||c.check)}</small><br>${esc(window.ResearchSemantics.displayCheckName(c.name))}${c.name==='IC 레짐 집중도'?'<small class="muted block">원문: IC 레짐 집중도 · 시장 국면이 아닌 동일 길이 시간 4구간 검사</small>':''}</td><td>${badge(c.passed===true?'PASS':c.passed===false?'FAIL':'미검증',c.passed===true?'green':c.passed===false?'red':'neutral')}</td><td>${esc(typeof c.value==='object'?JSON.stringify(c.value):c.value??'—')}</td><td>${esc(c.threshold||'—')}<small class="muted block">${esc(c.note)}</small></td></tr>`).join('')}</tbody></table></div>`).join('')}</details><details class="source"><summary>정의 · 입력 · 계산 코드</summary>${tree(r.definition)}</details><details class="source"><summary>공개 성능 전체와 기간</summary>${tree(r.performance)}</details><details class="source"><summary>입력 품질 · 경제적 결과 · 통제 비교 등 전체 진단</summary>${tree(r.diagnostics)}</details><details class="source"><summary>원본 출처 · 증거 해시 · 검증 상태</summary>${tree(r.provenance)}</details><div class="download-row"><button class="small-button" data-download="${esc(id)}">이 연구의 공개 근거 JSON ↓</button>${r.regimes?.monthly?.length?'<a class="small-button" data-close-link href="#regimes">레짐 전체 상태 탐색 ↗</a>':''}</div></div>`);}
Object.assign(macroNames,{KR_PRODUCTION_INFLATION_DIRECTION:'한국 생산·물가 방향 · 별도 설명 분류'});
Object.assign(stateNames,{PRODUCTION_UP_INFLATION_DOWN:'생산 개선 · 물가상승률 둔화',PRODUCTION_UP_INFLATION_UP:'생산 개선 · 물가상승률 가속',PRODUCTION_DOWN_INFLATION_UP:'생산 악화 · 물가상승률 가속',PRODUCTION_DOWN_INFLATION_DOWN:'생산 악화 · 물가상승률 둔화',NEUTRAL:'한 축 이상 변화 없음'});
function lessonResults(){
 const q=(ui.lessonQuery||'').trim().toLowerCase();
 const rows=sortedLessons().filter(r=>[r.factor_name,title(r.factor_name),r.campaign_id,r.definition.hypothesis,lessonTitle(r),reviewLabel(r.review.stance),r.review.general_lesson,r.review.economic_interpretation,r.review.lesson_key].join(' ').toLowerCase().includes(q));
 return `<div class="table-caption"><strong>${rows.length}개 교훈</strong><span>최신 연구순 · 캠페인 날짜 ↓ · 같은 날은 시행 번호 ↓</span></div><div class="two-grid section-gap">${rows.map(r=>lessonCard(r)).join('')||empty('검색어에 맞는 검토된 교훈이 없습니다.')}</div>`;
}
document.addEventListener('input',e=>{if(e.target.id==='lesson-search'){ui.lessonQuery=e.target.value;$('#lesson-results').innerHTML=lessonResults();}});

function inputReadiness(){
 const p=research.regime_input_snapshot;if(!p)return notice('보존된 입력 준비 상태가 없습니다. 아래 과거 연구와 구분합니다.');
 const audit=window.ResearchSemantics.displayFreshness(p,window.ResearchSemantics.displayAuditAsOf),g=p.contexts.find(c=>c.context_id==='KR_PRODUCTION_INFLATION_DIRECTION');
 const labels={PRODUCTION_UP_INFLATION_DOWN:'생산 모멘텀 개선 · 물가상승률 둔화',PRODUCTION_UP_INFLATION_UP:'생산 모멘텀 개선 · 물가상승률 가속',PRODUCTION_DOWN_INFLATION_UP:'생산 모멘텀 악화 · 물가상승률 가속',PRODUCTION_DOWN_INFLATION_DOWN:'생산 모멘텀 악화 · 물가상승률 둔화',NEUTRAL:'한 축 이상 변화 없음'};
 return `<details class="panel section-gap input-readiness"><summary><strong>입력 최신성 · ${audit.display_audit_as_of} 점검</strong><span>필요 완료월 ${audit.expected_completed_month} · 보존 자료에서 ${audit.current_ready_contexts}/${audit.context_count}축 확인</span></summary><p>원천 스냅샷은 ${esc(p.as_of)}이며 당시 완료월 ${esc(p.last_completed_month)}에 ${p.current_ready_contexts}/${p.context_count}축이 준비돼 있었습니다. 위 숫자는 새 기준월과 기존 자료 범위를 대조한 결과이며, 데이터를 새로 수집하거나 상태를 재계산한 것이 아닙니다. 수집 지연과 공식 발표 시차는 원천별로 따로 확인해야 합니다.</p>${g?`<h3>보존된 한국 생산·물가 방향</h3><p><strong>${esc(labels[g.latest_primary_state]||g.latest_primary_state)}</strong> · 자료월 ${esc(g.data_latest_month)} · ${badge('PIT_ASSUMED','amber')}</p><p>연속 여섯 판단월의 가용값으로 최근 석 달 평균과 앞선 석 달 평균을 비교합니다. GDP·공식 침체 판정이 아니며 기존 연구에 소급 적용하지 않았습니다. 현재월 값으로 이어 붙이지 않습니다.</p>`:''}<details class="source"><summary>입력 ${audit.context_count}개의 원천·기간·가용성 전체</summary><div class="table-wrap"><table><thead><tr><th>입력 / 원래 식별자</th><th>최종 자료월</th><th>유효 과거 개월</th><th>${audit.expected_completed_month} 지원</th><th>PIT</th></tr></thead><tbody>${audit.contexts.map(c=>`<tr><td>${esc(window.ResearchSemantics.contextLabel(c.context_id))}<code>${esc(c.context_id)}</code></td><td>${esc(c.data_latest_month||'미확인')}</td><td>${c.usable_months}</td><td>${badge(c.display_freshness.current_state_ready?'보존 자료 있음':'현 기준월 미확인',c.display_freshness.current_state_ready?'blue':'amber')}</td><td>${esc(c.pit_status)}</td></tr>`).join('')}</tbody></table></div></details></details>`;
}
function regimePage(){return regimes();}
function researchMap(){return window.ResearchMapUI?window.ResearchMapUI.render(research,{title},render):'<section class="panel"><h1>연구 지도</h1><p>연결 정보를 불러오는 중입니다.</p><a href="#lessons">기존 레슨 런 보기 ↗</a></section>';}
window.addEventListener('research-map-ready',()=>{if(location.hash.startsWith('#map'))render();});
function coveragePage(){return window.ResearchStatusUI.render(research,{title},()=>{if(location.hash.startsWith('#coverage'))render();});}
function researchV2Page(){return window.ResearchV2UI.render(()=>{if(location.hash.startsWith('#research-v2'))render();});}
const routes={'research-v2':{name:'새 연구 절차',render:researchV2Page},coverage:{name:'팩터 공간',render:coveragePage},map:{name:'연구 지도',render:researchMap},overview:{name:'연구 현황',render:overview},factors:{name:'승인 팩터',render:factors},lessons:{name:'레슨 런',render:lessons},regimes:{name:'레짐 탐색',render:regimePage},comparison:{name:'월초 실행 비교',render:comparisonPage},studies:{name:'연구 아카이브',render:studies},method:{name:'근거와 방법론',render:method}};
function render(){
 if(!research)return;
 const rawRoute=location.hash.slice(1).split('?')[0]||'overview',route=['coverage-domains','coverage-templates'].includes(rawRoute)?'coverage':rawRoute,page=routes[route]||routes.overview;
 const v2Link=['overview','lessons','regimes','map'].includes(route)?notice('이번 여섯 팩터의 교훈과 새 국면 진단은 <a href="#research-v2"><strong>새 연구 절차</strong></a>에서 봅니다. 아래 기존 연구 기록과 별도로 보존했습니다.','blue'):'';
 $('#main').innerHTML=v2Link+page.render();$('#breadcrumb').textContent=page.name;
 $('.snapshot-label').textContent=route==='research-v2'?`새 진단·교훈 · ${window.ResearchV2UI.snapshotDate()||'불러오는 중'}`:`연구 · ${date(research.as_of)} / 승인 · ${comparison?date(comparison.as_of):'미확인'}`;
 document.title=`${page.name} · TeamAlpha Research Observatory`;
 if(route==='coverage')window.ResearchStatusUI.afterRender();
 document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.hasAttribute('data-close')||t.hasAttribute('data-close-link'))$('#detail-dialog').close();if(t.dataset.record)openRecord(t.dataset.record);if(t.dataset.factor)openFactor(t.dataset.factor);if(t.dataset.page){ui.page=Number(t.dataset.page);$('#study-results').innerHTML=studyResults();$('#study-results').scrollIntoView({block:'start'});}if(t.dataset.metric){ui.metric=t.dataset.metric;render();}if(t.dataset.download){const r=research.records.find(x=>x.record_id===t.dataset.download),url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`${r.factor_name}-research.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
document.addEventListener('input',e=>{if(e.target.id==='factor-search'){ui.factorQuery=e.target.value;$('#factor-results').innerHTML=factorResults();}if(e.target.id==='study-search'){ui.query=e.target.value;ui.page=1;$('#study-results').innerHTML=studyResults();}});
document.addEventListener('change',e=>{if(e.target.id==='regime-study'){ui.regimeStudy=e.target.value;ui.axis='regime';render();return;}const key=({'factor-category':'category','factor-sort':'factorSort','study-verdict':'verdict','study-review':'review','study-family':'family','regime-axis':'axis'})[e.target.id];if(!key)return;ui[key]=e.target.value;if(key==='category'||key==='factorSort')$('#factor-results').innerHTML=factorResults();else if(key==='axis')$('#regime-results').innerHTML=regimeResults();else{ui.page=1;$('#study-results').innerHTML=studyResults();}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{window.scrollTo({top:0});render();});
Promise.all([
 ...['research-catalog','gold-catalog'].map(n=>fetch(`./data/${n}.json`).then(r=>{if(!r.ok)throw new Error('Snapshot unavailable');return r.json();})),
 fetch('./data/monthly-comparison.json').then(r=>{if(!r.ok)throw new Error('Comparison unavailable');return r.json();}).then(c=>{if(c.schema_version!=='public-monthly-comparison-readiness-v1'||c.real_performance_computed!==false||!Array.isArray(c.factors))throw new Error('Unsupported comparison snapshot');return c;}).catch(()=>null)
]).then(([r,g,c])=>{research=r;gold=g;comparison=c;({latestResearch,selectedRegimeStudy}=window.ResearchSemantics.selectStudies(r));$('.snapshot-label').textContent=`연구 · ${date(r.as_of)} / 승인 · ${c?date(c.as_of):'미확인'}`;render();}).catch(()=>{$('#main').innerHTML=head('DATA UNAVAILABLE','연구 스냅샷을 불러오지 못했습니다.','연결을 확인한 뒤 페이지를 다시 열어 주세요. 값을 임의로 채우지 않습니다.')+'<button class="button" onclick="location.reload()">다시 불러오기</button>';});
